styles:
:root {
  --primary: #d97706;
  --primary-dark: #b45309;
  --primary-light: #fef3c7;
  --accent: #f59e0b;
  --success: #10b981;
  --card-bg: #ffffff;
  --text-main: #1f2937;
  --text-muted: #6b7280;
}

body {
  margin: 0;
  padding: 0;
  background: #fffdf7;
  font-family: 'Noto Sans KR', sans-serif;
  color: var(--text-main);
  -webkit-font-smoothing: antialiased;
  user-select: none;
}

/* 상단 탑바 */
.top-header {
  background: #ffffff;
  border-bottom: 2px solid #fde68a;
  padding: 12px 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: 0 4px 12px rgba(217, 119, 6, 0.08);
}
.header-left {
  display: flex;
  align-items: center;
  gap: 12px;
}
.btn-nav-back {
  background: #fef3c7;
  color: #b45309;
  border: 2px solid #f59e0b;
  border-radius: 14px;
  padding: 6px 14px;
  font-family: 'Jua', sans-serif;
  font-size: 1rem;
  cursor: pointer;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transition: all 0.2s;
}
.btn-nav-back:hover {
  background: #fde68a;
  transform: translateY(-2px);
}
.header-title-box h1 {
  margin: 0;
  font-family: 'Jua', sans-serif;
  font-size: 1.4rem;
  color: #78350f;
  display: flex;
  align-items: center;
  gap: 8px;
}
.header-right {
  display: flex;
  align-items: center;
  gap: 12px;
}
.gem-badge {
  background: #eff6ff;
  border: 2px solid #3b82f6;
  border-radius: 20px;
  padding: 4px 12px;
  font-family: 'Jua', sans-serif;
  font-size: 1rem;
  color: #1d4ed8;
  display: flex;
  align-items: center;
  gap: 6px;
}

/* 메인 컨테이너 */
.training-container {
  max-width: 920px;
  margin: 0 auto;
  padding: 24px 16px 80px;
}

/* 상단 모드 전환 탭 (Mode 1 vs Mode 2) */
.mode-tab-bar {
  display: flex;
  background: #fef3c7;
  padding: 6px;
  border-radius: 20px;
  margin-bottom: 24px;
  gap: 6px;
  border: 2px solid #fde68a;
}
.mode-tab-btn {
  flex: 1;
  padding: 12px 16px;
  border: none;
  background: transparent;
  border-radius: 14px;
  font-family: 'Jua', sans-serif;
  font-size: 1.15rem;
  color: #92400e;
  cursor: pointer;
  transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
.mode-tab-btn.active {
  background: #ffffff;
  color: #b45309;
  box-shadow: 0 4px 12px rgba(217, 119, 6, 0.15);
  font-weight: 800;
  transform: scale(1.02);
}

/* 공통 카드 스타일 */
.train-card {
  background: #ffffff;
  border: 3px solid #fde68a;
  border-radius: 28px;
  padding: 28px 24px;
  box-shadow: 0 8px 24px rgba(217, 119, 6, 0.1);
  position: relative;
}

/* ======================================================== */
/* 📐 교과서 실물 정품 세로 분수 (Vertical Fraction)       */
/* ======================================================== */
.inline-frac {
  display: inline-flex;
  flex-direction: column;
  vertical-align: middle;
  text-align: center;
  padding: 0 4px;
  font-size: 1.05em;
  line-height: 1.1;
  font-weight: 700;
}
.inline-frac .num {
  display: block;
  padding-bottom: 2px;
}
.inline-frac .bar {
  display: block;
  border-top: 2px solid currentColor;
  height: 0;
  width: 100%;
  min-width: 16px;
  margin: 2px 0;
  font-size: 0;
}
.inline-frac .den {
  display: block;
  padding-top: 2px;
}

/* 대분수 래퍼 */
.mixed-frac {
  display: inline-flex;
  align-items: center;
  vertical-align: middle;
  gap: 3px;
  font-weight: 700;
}
.mixed-frac .whole {
  font-size: 1.25em;
  line-height: 1;
  color: currentColor;
}

/* 🧱 Mode 1: 6대 파트 대분류 탭 */
.category-pills-bar {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 16px;
  justify-content: center;
}
.cat-pill {
  background: #f9fafb;
  border: 2px solid #e5e7eb;
  border-radius: 14px;
  padding: 8px 14px;
  font-family: 'Jua', sans-serif;
  font-size: 0.95rem;
  color: #4b5563;
  cursor: pointer;
  transition: all 0.2s;
}
.cat-pill:hover {
  border-color: #f59e0b;
  color: #b45309;
}
.cat-pill.active {
  background: #fef3c7;
  border-color: #f59e0b;
  color: #b45309;
  font-weight: bold;
  box-shadow: 0 4px 10px rgba(245, 158, 11, 0.2);
}

/* 서브 문제 번호 선택 바 (1번~5번 + 랜덤) */
.sub-problem-bar {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 24px;
  padding: 10px;
  background: #fefce8;
  border-radius: 18px;
  border: 1.5px dashed #fcd34d;
}
.prob-num-btn {
  background: #ffffff;
  border: 2px solid #e2e8f0;
  border-radius: 12px;
  padding: 6px 14px;
  font-family: 'Jua', sans-serif;
  font-size: 0.95rem;
  color: #475569;
  cursor: pointer;
  transition: all 0.2s;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.prob-num-btn:hover {
  border-color: #3b82f6;
  color: #1d4ed8;
}
.prob-num-btn.active {
  background: #3b82f6;
  border-color: #2563eb;
  color: #ffffff;
  font-weight: bold;
  box-shadow: 0 4px 10px rgba(59, 130, 246, 0.3);
}
.prob-num-btn.done::after {
  content: ' ✔';
  color: #10b981;
  font-weight: bold;
}
.prob-num-btn.active.done::after {
  color: #a7f3d0;
}
.btn-random-generate {
  background: linear-gradient(135deg, #10b981, #059669);
  border: 2px solid #047857;
  color: #ffffff;
  border-radius: 12px;
  padding: 6px 16px;
  font-family: 'Jua', sans-serif;
  font-size: 0.95rem;
  cursor: pointer;
  box-shadow: 0 4px 10px rgba(16, 185, 129, 0.25);
  transition: all 0.2s;
}
.btn-random-generate:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 14px rgba(16, 185, 129, 0.35);
}

/* 문제 타이틀 박스 */
.problem-hero-box {
  background: linear-gradient(135deg, #fffbeb, #fef3c7);
  border: 2px solid #fcd34d;
  border-radius: 20px;
  padding: 20px 24px;
  text-align: center;
  margin-bottom: 24px;
}
.problem-badge {
  display: inline-block;
  background: #d97706;
  color: #ffffff;
  padding: 4px 12px;
  border-radius: 12px;
  font-family: 'Jua', sans-serif;
  font-size: 0.9rem;
  margin-bottom: 10px;
}
.problem-title {
  font-family: 'Jua', sans-serif;
  font-size: 2.2rem;
  color: #78350f;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
}

/* 단계별 연산 비계(Scaffolding) 스텝 */
.scaffold-steps-wrap {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.step-row {
  background: #f8fafc;
  border: 2px solid #e2e8f0;
  border-radius: 18px;
  padding: 16px 20px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  transition: all 0.3s;
}
.step-row.active {
  border-color: #f59e0b;
  background: #fffdf5;
  box-shadow: 0 6px 16px rgba(245, 158, 11, 0.12);
}
.step-row.done {
  border-color: #10b981;
  background: #f0fdf4;
}
.step-info {
  display: flex;
  align-items: center;
  gap: 10px;
}
.step-badge {
  background: #e2e8f0;
  color: #475569;
  font-family: 'Jua', sans-serif;
  font-size: 0.85rem;
  padding: 3px 10px;
  border-radius: 8px;
}
.step-row.active .step-badge {
  background: #f59e0b;
  color: #ffffff;
}
.step-row.done .step-badge {
  background: #10b981;
  color: #ffffff;
}
.step-desc {
  font-size: 1.05rem;
  font-weight: 600;
  color: #334155;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}
.step-formula-area {
  font-family: 'Jua', sans-serif;
  font-size: 1.8rem;
  color: #1e293b;
  padding: 8px 12px;
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

/* 빈칸 인풋 */
.blank-input {
  width: 54px;
  height: 48px;
  border: 3px dashed #d97706;
  border-radius: 12px;
  background: #ffffff;
  text-align: center;
  font-family: 'Jua', sans-serif;
  font-size: 1.6rem;
  color: #b45309;
  outline: none;
  transition: all 0.2s;
}
.blank-input:focus {
  border-style: solid;
  border-color: #2563eb;
  background: #eff6ff;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.2);
}
.blank-input.correct {
  border-style: solid;
  border-color: #10b981;
  background: #d1fae5;
  color: #047857;
  pointer-events: none;
}

/* 힌트 알림창 */
.hint-alert-box {
  background: #fef2f2;
  border: 2px solid #fecaca;
  border-radius: 16px;
  padding: 14px 18px;
  margin-top: 16px;
  display: none;
  align-items: center;
  gap: 12px;
  color: #991b1b;
  font-size: 1rem;
  font-weight: 600;
}

/* 온스크린 키패드 */
.keypad-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 8px;
  max-width: 480px;
  margin: 16px auto 0;
}
.keypad-btn {
  background: #ffffff;
  border: 2px solid #e2e8f0;
  border-radius: 12px;
  padding: 12px 0;
  font-family: 'Jua', sans-serif;
  font-size: 1.3rem;
  color: #334155;
  cursor: pointer;
  box-shadow: 0 3px 6px rgba(0,0,0,0.04);
  transition: all 0.15s;
}
.keypad-btn:active {
  transform: scale(0.95);
  background: #f1f5f9;
}

/* ⚔️ Mode 2: 퀴즈 배틀 */
.quiz-progress-bar {
  display: flex;
  justify-content: space-between;
  font-family: 'Jua', sans-serif;
  color: #64748b;
  margin-bottom: 12px;
}
.quiz-question-box {
  background: linear-gradient(135deg, #fff7ed, #ffedd5);
  border: 2px solid #fdba74;
  border-radius: 20px;
  padding: 24px;
  margin-bottom: 24px;
  text-align: center;
}
.quiz-q-num {
  background: #ea580c;
  color: #ffffff;
  padding: 4px 12px;
  border-radius: 10px;
  font-family: 'Jua', sans-serif;
  font-size: 0.9rem;
  display: inline-block;
  margin-bottom: 12px;
}
.quiz-question-text {
  font-family: 'Jua', sans-serif;
  font-size: 1.5rem;
  color: #7c2d12;
  line-height: 1.5;
  margin: 0;
  word-break: keep-all;
}
.quiz-options-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.quiz-opt-btn {
  background: #ffffff;
  border: 2px solid #e2e8f0;
  border-radius: 16px;
  padding: 16px 20px;
  text-align: left;
  font-family: 'Jua', sans-serif;
  font-size: 1.25rem;
  color: #334155;
  cursor: pointer;
  transition: all 0.2s;
  display: flex;
  align-items: center;
  gap: 14px;
}
.quiz-opt-btn:hover {
  border-color: #f59e0b;
  background: #fffdf5;
  transform: translateX(4px);
}
.quiz-opt-num {
  width: 32px;
  height: 32px;
  background: #f1f5f9;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #64748b;
  font-size: 1rem;
  flex-shrink: 0;
}
.quiz-opt-btn.correct {
  background: #d1fae5 !important;
  border-color: #10b981 !important;
  color: #047857 !important;
}
.quiz-opt-btn.wrong {
  background: #fee2e2 !important;
  border-color: #ef4444 !important;
  color: #b91c1c !important;
}

/* 팝업 모달 */
.train-modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  backdrop-filter: blur(6px);
  display: none;
  align-items: center;
  justify-content: center;
  z-index: 1000;
}
.train-modal-box {
  background: #ffffff;
  border-radius: 28px;
  max-width: 440px;
  width: 90%;
  padding: 32px 24px;
  text-align: center;
  border: 3px solid #fde68a;
  box-shadow: 0 20px 40px rgba(0,0,0,0.2);
}
.modal-trophy {
  font-size: 4rem;
  margin-bottom: 12px;
}
.modal-title {
  font-family: 'Jua', sans-serif;
  font-size: 1.8rem;
  color: #78350f;
  margin-bottom: 10px;
}
.modal-desc {
  font-size: 1.05rem;
  color: #64748b;
  line-height: 1.6;
  margin-bottom: 24px;
  word-break: keep-all;
}
.btn-modal-action {
  background: linear-gradient(135deg, #f59e0b, #d97706);
  color: #ffffff;
  border: none;
  border-radius: 16px;
  padding: 12px 32px;
  font-family: 'Jua', sans-serif;
  font-size: 1.2rem;
  cursor: pointer;
  box-shadow: 0 6px 16px rgba(217, 119, 6, 0.3);
  transition: all 0.2s;
}
.btn-modal-action:hover {
  transform: translateY(-2px);
}

@media (max-width: 640px) {
  .problem-title { font-size: 1.6rem; }
  .step-formula-area { font-size: 1.4rem; }
  .blank-input { width: 46px; height: 42px; font-size: 1.3rem; }
  .keypad-grid { max-width: 100%; }
  .keypad-btn { font-size: 1.15rem; padding: 10px 0; }
}

scripts:
// ========================================================
// 🔊 사운드 및 보상 헬퍼
// ========================================================
let audioCtx = null;
function getAudioCtx() {
  if (!audioCtx) {
    audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  }
  return audioCtx;
}

function playSfx(type) {
  try {
    const ctx = getAudioCtx();
    if (ctx.state === 'suspended') ctx.resume();

    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);

    const now = ctx.currentTime;

    if (type === 'correct') {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(523.25, now);
      osc.frequency.exponentialRampToValueAtTime(783.99, now + 0.15);
      gain.gain.setValueAtTime(0.3, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
      osc.start(now);
      osc.stop(now + 0.3);
    } else if (type === 'wrong') {
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(220, now);
      osc.frequency.setValueAtTime(196, now + 0.1);
      gain.gain.setValueAtTime(0.2, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.25);
      osc.start(now);
      osc.stop(now + 0.25);
    } else if (type === 'click') {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(800, now);
      gain.gain.setValueAtTime(0.1, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.05);
      osc.start(now);
      osc.stop(now + 0.05);
    } else if (type === 'fanfare') {
      const notes = [523.25, 659.25, 783.99, 1046.5];
      notes.forEach((freq, i) => {
        const o = ctx.createOscillator();
        const g = ctx.createGain();
        o.connect(g);
        g.connect(ctx.destination);
        o.type = 'triangle';
        o.frequency.setValueAtTime(freq, now + i * 0.1);
        g.gain.setValueAtTime(0.25, now + i * 0.1);
        g.gain.exponentialRampToValueAtTime(0.01, now + i * 0.1 + 0.35);
        o.start(now + i * 0.1);
        o.stop(now + i * 0.1 + 0.35);
      });
    }
  } catch (e) {
    console.warn("Audio error:", e);
  }
}

function getGemCount() {
  return parseInt(localStorage.getItem('minmin_gems') || '0', 10);
}
function addGems(amount) {
  const cur = getGemCount() + amount;
  localStorage.setItem('minmin_gems', cur.toString());
  document.getElementById('gemCount').textContent = cur;
}

// ========================================================
// 📐 정품 세로 분수 HTML 생성 헬퍼 (슬래시 분수 표기 완전 제거)
// ========================================================
function renderFrac(num, den) {
  return `<span class="inline-frac"><span class="num">${num}</span><span class="bar"></span><span class="den">${den}</span></span>`;
}

function renderMixed(whole, num, den) {
  return `<span class="mixed-frac"><span class="whole">${whole}</span><span class="inline-frac"><span class="num">${num}</span><span class="bar"></span><span class="den">${den}</span></span></span>`;
}

// ========================================================
// 🧱 1. 단계별 빈칸 연산 훈련소 (6대 파트별 문제 은행 & 랜덤 생성)
// ========================================================
let trainMode = 'scaffold'; // 'scaffold' | 'battle'
let curCatIdx = 0;          // 0: 진분수x자연수, 1: 가분수탈출, 2: 대분수x자연수, 3: 자연수x진분수, 4: 진분수x진분수, 5: 대분수x대분수
let curProbIdx = 0;         // 0~4 (기본 5문제) or -1 (랜덤 생성 문제)
let customRandomProb = null;// 랜덤 생성 문제 임시 저장
let solvedMap = {};         // key: `${cat}_${prob}`, val: true

const CATEGORIES = [
  { name: "🍕 진분수 × 자연수", desc: "분모는 쉬고, 분자에만 자연수를 곱해요!" },
  { name: "🐸 가분수 탈출", desc: "분자가 분모보다 커지면 대분수로 변신!" },
  { name: "🧪 대분수 × 자연수", desc: "가분수 투구를 씌운 뒤 곱하고 대분수로 정리!" },
  { name: "🧶 자연수 × 진분수", desc: "자연수와 분모를 미리 싹둑 약분해요!" },
  { name: "💎 진분수 × 진분수", desc: "대각선 번개 약분 후 분모끼리, 분자끼리 곱해요!" },
  { name: "👑 대분수 × 대분수", desc: "양쪽 모두 가분수로 바꾼 뒤 번개 약분!" }
];

// 각 카테고리별 정선된 5개 문제 세트 (총 30문제)
const PROBLEM_BANKS = {
  // Part 0: 진분수 x 자연수 (결과가 진분수)
  0: [
    {
      hero: `${renderFrac(1, 3)} × 2`,
      steps: [
        { desc: "자연수 2는 분자에만 쏙 곱해요!", formula: `${renderFrac(`1 × <input class="blank-input" id="inp_s_0" data-ans="2" maxlength="2" onkeyup="checkInput(this)">`, 3)}`, hint: "자연수 2를 분자 자리에 넣으세요!" },
        { desc: "분자 1 × 2를 계산하면?", formula: `= ${renderFrac(`<input class="blank-input" id="inp_s_1" data-ans="2" maxlength="2" onkeyup="checkInput(this)">`, 3)}`, hint: "1 곱하기 2는 2예요!" }
      ]
    },
    {
      hero: `${renderFrac(1, 4)} × 3`,
      steps: [
        { desc: "자연수 3을 분자에만 곱해요!", formula: `${renderFrac(`1 × <input class="blank-input" id="inp_s_0" data-ans="3" maxlength="2" onkeyup="checkInput(this)">`, 4)}`, hint: "자연수 3을 분자 자리에 써보세요!" },
        { desc: "분자 1 × 3을 계산하면?", formula: `= ${renderFrac(`<input class="blank-input" id="inp_s_1" data-ans="3" maxlength="2" onkeyup="checkInput(this)">`, 4)}`, hint: "1 곱하기 3은 3이에요!" }
      ]
