// ========================================================
// 🎲 무한 랜덤 문제 생성 알고리즘
// ========================================================
function generateRandomProblem(catIdx) {
  if (catIdx === 0) {
    // 진분수 x 자연수 (결과 진분수)
    const dens = [5, 6, 7, 8, 9, 10];
    const d = dens[Math.floor(Math.random() * dens.length)];
    const n = Math.floor(Math.random() * 2) + 1; // 1 or 2
    const m = Math.floor(Math.random() * (Math.floor((d - 1) / n) - 1)) + 2;
    const prod = n * m;
    return {
      hero: `${renderFrac(n, d)} × ${m}`,
      steps: [
        { desc: `자연수 ${m}은 분자에만 곱해요!`, formula: `${renderFrac(`${n} × <input class="blank-input" id="inp_s_0" data-ans="${m}" maxlength="2" onkeyup="checkInput(this)">`, d)}`, hint: `자연수 ${m}을 분자에 쏙 넣어보세요!` },
        { desc: `분자 ${n} × ${m}을 계산하면?`, formula: `= ${renderFrac(`<input class="blank-input" id="inp_s_1" data-ans="${prod}" maxlength="2" onkeyup="checkInput(this)">`, d)}`, hint: `${n} 곱하기 ${m}은 ${prod}이에요!` }
      ]
    };
  } else if (catIdx === 1) {
    // 가분수 탈출 (결과 대분수)
    const d = [3, 4, 5, 7][Math.floor(Math.random() * 4)];
    const n = Math.floor(Math.random() * (d - 1)) + 1;
    const m = Math.floor(Math.random() * 3) + 2;
    const prod = n * m;
    if (prod <= d) return generateRandomProblem(catIdx); // 가분수가 되도록 재시도
    const w = Math.floor(prod / d);
    const rem = prod % d;
    return {
      hero: `${renderFrac(n, d)} × ${m}`,
      steps: [
        { desc: `분자에 ${m}을 곱해요 (${n} × ${m})`, formula: `= ${renderFrac(`<input class="blank-input" id="inp_s_0" data-ans="${prod}" maxlength="2" onkeyup="checkInput(this)">`, d)}`, hint: `${n} 곱하기 ${m}은 ${prod}이에요!` },
        { desc: `가분수 ${renderFrac(prod, d)}를 대분수로 정리!`, formula: `= <input class="blank-input" id="inp_s_1" data-ans="${w}" maxlength="2" onkeyup="checkInput(this)">${renderFrac(`<input class="blank-input" id="inp_s_2" data-ans="${rem}" maxlength="2" onkeyup="checkInput(this)">`, d)}`, hint: `${prod} 안에 ${d}가 ${w}번 들어가고 ${rem}이 남아요!` }
      ]
    };
  } else if (catIdx === 2) {
    // 대분수 x 자연수
    const d = [3, 4, 5][Math.floor(Math.random() * 3)];
    const w = Math.floor(Math.random() * 2) + 1;
    const n = Math.floor(Math.random() * (d - 1)) + 1;
    const m = Math.floor(Math.random() * 2) + 2;
    const improper = w * d + n;
    const prod = improper * m;
    const finW = Math.floor(prod / d);
    const finRem = prod % d;
    return {
      hero: `${renderMixed(w, n, d)} × ${m}`,
      steps: [
        { desc: `대분수 ${renderMixed(w, n, d)}를 가분수로 변신!`, formula: `= ${renderFrac(`<input class="blank-input" id="inp_s_0" data-ans="${improper}" maxlength="2" onkeyup="checkInput(this)">`, d)} × ${m}`, hint: `${w}×${d}+${n} = ${improper}예요!` },
        { desc: `분자 ${improper}에 자연수 ${m} 곱하기`, formula: `= ${renderFrac(`<input class="blank-input" id="inp_s_1" data-ans="${prod}" maxlength="2" onkeyup="checkInput(this)">`, d)}`, hint: `${improper} 곱하기 ${m}은 ${prod}이에요!` },
        { desc: `가분수를 대분수로 정리!`, formula: `= <input class="blank-input" id="inp_s_2" data-ans="${finW}" maxlength="2" onkeyup="checkInput(this)">${renderFrac(`<input class="blank-input" id="inp_s_3" data-ans="${finRem}" maxlength="2" onkeyup="checkInput(this)">`, d)}`, hint: `${prod} 안에 ${d}가 ${finW}번 들어가고 ${finRem}이 남아요!` }
      ]
    };
  } else if (catIdx === 3) {
    // 자연수 x 진분수 (약분)
    const d = [3, 4, 5, 6][Math.floor(Math.random() * 4)];
    const mult = Math.floor(Math.random() * 3) + 2;
    const nat = d * mult;
    const n = Math.floor(Math.random() * (d - 1)) + 1;
    const ans = mult * n;
    return {
      hero: `${nat} × ${renderFrac(n, d)}`,
      steps: [
        { desc: `자연수 ${nat}과 분모 ${d}를 ${d}로 약분하면 ${nat}은?`, formula: `${nat}은 ➔ <input class="blank-input" id="inp_s_0" data-ans="${mult}" maxlength="2" onkeyup="checkInput(this)">`, hint: `${nat} 나누기 ${d}는 ${mult}이에요!` },
        { desc: `남은 수 ${mult} × ${n}을 계산하면?`, formula: `= <input class="blank-input" id="inp_s_1" data-ans="${ans}" maxlength="2" onkeyup="checkInput(this)">`, hint: `${mult} 곱하기 ${n}은 ${ans}이에요!` }
      ]
    };
  } else if (catIdx === 4) {
    // 단위/진분수 x 진분수
    const d1 = [2, 3, 4][Math.floor(Math.random() * 3)];
    const d2 = [3, 5, 7][Math.floor(Math.random() * 3)];
    const prodDen = d1 * d2;
    return {
      hero: `${renderFrac(1, d1)} × ${renderFrac(1, d2)}`,
      steps: [
        { desc: "분모끼리 곱하고, 분자끼리 곱해요!", formula: `= ${renderFrac("1 × 1", `<input class="blank-input" id="inp_s_0" data-ans="${d1}" maxlength="2" onkeyup="checkInput(this)"> × <input class="blank-input" id="inp_s_1" data-ans="${d2}" maxlength="2" onkeyup="checkInput(this)">`)}`, hint: `분모 ${d1}과 ${d2}를 분모 자리에 써요!` },
        { desc: `분모 ${d1} × ${d2}를 계산하면 전체 칸 수는?`, formula: `= ${renderFrac(1, `<input class="blank-input" id="inp_s_2" data-ans="${prodDen}" maxlength="2" onkeyup="checkInput(this)">`)}`, hint: `${d1} 곱하기 ${d2}는 ${prodDen}이에요!` }
      ]
    };
  } else {
    // 대분수 x 대분수
    return {
      hero: `${renderMixed(1, 1, 2)} × ${renderMixed(1, 1, 3)}`,
      steps: [
        { desc: `두 대분수를 가분수로 변신!`, formula: `= ${renderFrac(`<input class="blank-input" id="inp_s_0" data-ans="3" maxlength="2" onkeyup="checkInput(this)">`, 2)} × ${renderFrac(`<input class="blank-input" id="inp_s_1" data-ans="4" maxlength="2" onkeyup="checkInput(this)">`, 3)}`, hint: "1×2+1=3, 1×3+1=4예요!" },
        { desc: "3끼리 약분되고, 분자 4를 분모 2로 나누면 남는 자연수는?", formula: `= <input class="blank-input" id="inp_s_2" data-ans="2" maxlength="2" onkeyup="checkInput(this)">`, hint: "4 나누기 2는 2예요!" }
      ]
    };
  }
}

let lastFocusedInput = null;

function renderScaffoldMode() {
  const area = document.getElementById('mainTrainArea');

  // 1. 카테고리 알약 탭 (6대 파트)
  let catPillsHtml = CATEGORIES.map((cat, i) => `
    <button class="cat-pill ${i === curCatIdx ? 'active' : ''}" onclick="selectCategory(${i})">
      ${cat.name}
    </button>
  `).join('');

  // 2. 문제 번호 선택 바 (1번~5번 + 🎲 무한 랜덤 버튼)
  const isRandom = (curProbIdx === -1);
  let subPillsHtml = [0, 1, 2, 3, 4].map(pIdx => {
    const isSolved = solvedMap[`${curCatIdx}_${pIdx}`];
    return `
      <button class="prob-num-btn ${(!isRandom && curProbIdx === pIdx) ? 'active' : ''} ${isSolved ? 'done' : ''}" onclick="selectProblem(${pIdx})">
        ${pIdx + 1}번 문제
      </button>
    `;
  }).join('');

  subPillsHtml += `
    <button class="btn-random-generate" onclick="generateAndPlayRandom()">
      🎲 무한 랜덤 문제 뽑기!
    </button>
  `;

  // 현재 문제 객체 가져오기
  let prob;
  if (isRandom) {
    prob = customRandomProb || generateRandomProblem(curCatIdx);
    customRandomProb = prob;
  } else {
    prob = PROBLEM_BANKS[curCatIdx][curProbIdx];
  }

  // 3. 단계별 수식 스텝들
  let stepsHtml = prob.steps.map((st, sIdx) => `
    <div class="step-row ${sIdx === 0 ? 'active' : ''}" id="stepRow_${sIdx}">
      <div class="step-info">
        <span class="step-badge">${sIdx + 1}단계</span>
        <span class="step-desc">${st.desc}</span>
      </div>
      <div class="step-formula-area">
        ${st.formula}
      </div>
    </div>
  `).join('');

  area.innerHTML = `
    <!-- 6대 카테고리 탭 -->
    <div class="category-pills-bar">${catPillsHtml}</div>

    <!-- 1~5번 및 랜덤 선택 바 -->
    <div class="sub-problem-bar">${subPillsHtml}</div>

    <!-- 문제 헤로 박스 -->
    <div class="problem-hero-box">
      <span class="problem-badge">${CATEGORIES[curCatIdx].name}</span>
      <div class="problem-title">${prob.hero}</div>
    </div>

    <!-- 단계별 비계 입력 -->
    <div class="scaffold-steps-wrap">
      ${stepsHtml}
    </div>

    <!-- 코코 힌트 박스 -->
    <div class="hint-alert-box" id="hintAlertBox">
      <span style="font-size:1.4rem;">💡</span>
      <span id="hintAlertText">힌트가 여기에 표시됩니다.</span>
    </div>

    <!-- 온스크린 키패드 -->
    <div style="margin-top:24px; text-align:center;">
      <span style="font-family:'Jua'; color:#9ca3af; font-size:0.95rem;">📱 터치 입력 키패드</span>
      <div class="keypad-grid">
        ${[1,2,3,4,5,6,7,8,9,0].map(n => `<button class="keypad-btn" onclick="pressKeypad('${n}')">${n}</button>`).join('')}
        <button class="keypad-btn" style="color:#ef4444;" onclick="pressKeypad('del')">지우기 ⌫</button>
        <button class="keypad-btn" style="color:#047857;" onclick="pressKeypad('next')">다음 ➔</button>
      </div>
    </div>
  `;

  // 첫 번째 인풋 포커스
  setTimeout(() => {
    const firstInp = document.getElementById('inp_s_0');
    if (firstInp) {
      firstInp.focus();
      lastFocusedInput = firstInp;
    }
  }, 100);

  // 인풋 포커스 이벤트 연결
  document.querySelectorAll('.blank-input').forEach(inp => {
    inp.addEventListener('focus', () => { lastFocusedInput = inp; });
  });
}

function selectCategory(catIdx) {
  playSfx('click');
  curCatIdx = catIdx;
  curProbIdx = 0;
  customRandomProb = null;
  renderScaffoldMode();
}

function selectProblem(pIdx) {
  playSfx('click');
  curProbIdx = pIdx;
  customRandomProb = null;
  renderScaffoldMode();
}

function generateAndPlayRandom() {
  playSfx('click');
  curProbIdx = -1;
  customRandomProb = generateRandomProblem(curCatIdx);
  renderScaffoldMode();
}

function checkInput(inp) {
  const userVal = inp.value.trim();
  const correctAns = inp.getAttribute('data-ans');

  if (userVal === correctAns) {
    inp.classList.add('correct');
    playSfx('correct');
    hideHint();

    const inputs = Array.from(document.querySelectorAll('.blank-input'));
    const currIdx = inputs.indexOf(inp);
    const nextInp = inputs[currIdx + 1];

    if (nextInp) {
      nextInp.focus();
      lastFocusedInput = nextInp;
      const nextRow = nextInp.closest('.step-row');
      if (nextRow) nextRow.classList.add('active');
    } else {
      // 모든 단계 정답 완료!
      playSfx('fanfare');
      addGems(1);
      document.querySelectorAll('.step-row').forEach(r => r.classList.add('done'));

      if (curProbIdx >= 0) {
        solvedMap[`${curCatIdx}_${curProbIdx}`] = true;
      }

      showTrainModal("🎉 문제 정복 완료! 💎 +1 획득", "교과서 계산 공식을 완벽하게 마스터했습니다!");
    }
  } else if (userVal.length >= correctAns.length) {
    playSfx('wrong');
    showHint(inp);
  }
}

function showHint(inp) {
  let prob;
  if (curProbIdx === -1) {
    prob = customRandomProb;
  } else {
    prob = PROBLEM_BANKS[curCatIdx][curProbIdx];
  }
  const row = inp.closest('.step-row');
  const stepIdx = Array.from(document.querySelectorAll('.step-row')).indexOf(row);
  const hintText = prob?.steps[stepIdx]?.hint || "다시 한번 차근차근 생각해 보세요!";

  const box = document.getElementById('hintAlertBox');
  const txt = document.getElementById('hintAlertText');
  if (box && txt) {
    txt.textContent = hintText;
    box.style.display = 'flex';
  }
}

function hideHint() {
  const box = document.getElementById('hintAlertBox');
  if (box) box.style.display = 'none';
}

function pressKeypad(key) {
  if (!lastFocusedInput) return;
  if (key === 'del') {
    lastFocusedInput.value = '';
    playSfx('click');
  } else if (key === 'next') {
    const inputs = Array.from(document.querySelectorAll('.blank-input'));
    const idx = inputs.indexOf(lastFocusedInput);
    if (inputs[idx + 1]) inputs[idx + 1].focus();
  } else {
    lastFocusedInput.value = lastFocusedInput.value + key;
    checkInput(lastFocusedInput);
  }
}

